mapper.select:
SELECT g.id, g.loss_gain_no, g.warehouse_id, g.adjust_type, g.status, g.reason, g.remark, g.audited_at, g.auditor, g.audit_opinion, g.version, g.created_at, g.updated_at, w.warehouse_code, w.name AS warehouse_name FROM inventory_loss_gain g LEFT JOIN warehouse w ON w.id = g.warehouse_id WHERE g.deleted = FALSE
AND g.warehouse_id IN #{scopeId}
AND FALSE
AND g.loss_gain_no ILIKE CONCAT('%', #{query.lossGainNo}, '%')
AND g.warehouse_id = #{query.warehouseId}
AND g.adjust_type = #{query.adjustType}
AND g.status = #{query.status}
ORDER BY g.created_at DESC, g.id DESC
